# ---------------------------------------------------------------------------
# independent authority canonicaliser (test-side oracle)
# ---------------------------------------------------------------------------

import ipaddress as _ip

def _t_port(p):
    if not (1 <= len(p) <= 5) or not p.isdigit():
        return None
    v = int(p)
    return v if 1 <= v <= 65535 else None

def _t_dns(h):
    if not (1 <= len(h) <= 253):
        return None
    labels = h.split('.')
    if len(labels) == 4 and all(l and all('0' <= c <= '9' for c in l) for l in labels):
        for l in labels:
            if (len(l) > 1 and l[0] == '0') or int(l) > 255:
                return None
        return '.'.join(str(int(l)) for l in labels)
    for l in labels:
        if not (1 <= len(l) <= 63):
            return None
        for i, c in enumerate(l):
            if c == '-':
                if i == 0 or i == len(l) - 1:
                    return None
            elif not (('a' <= c <= 'z') or ('A' <= c <= 'Z') or ('0' <= c <= '9')):
                return None
    return h.lower()

def test_canon(authority, scheme):
    port = None
    if authority.startswith('['):
        end = authority.find(']')
        if end < 0:
            return None
        inner, rest = authority[1:end], authority[end+1:]
        if '%' in inner:
            return None
        if rest:
            if not rest.startswith(':'):
                return None
            port = _t_port(rest[1:])
            if port is None:
                return None
        try:
            host = '[' + _ip.IPv6Address(inner).compressed + ']'
        except ValueError:
            return None
    else:
        if ':' in authority:
            i = authority.index(':')
            hostpart, port = authority[:i], _t_port(authority[i+1:])
            if port is None:
                return None
        else:
            hostpart = authority
        host = _t_dns(hostpart)
        if host is None:
            return None
    if port is not None and port != {'http': 80, 'https': 443}[scheme]:
        host += ':' + str(port)
    return host

def routes_for(pairs_of_scheme_authority, base=None):
    """Routes covering every (scheme, authority) pair mentioned in fields."""
    out = dict(base or {})
    for scheme, authority in pairs_of_scheme_authority:
        canon = test_canon(authority, scheme)
        if canon is not None:
            out.setdefault(scheme + '://' + canon, 'auto')
    return out
